<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Pembayaran - CozyCafe</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= e(BASE_URL) ?>/assets/css/style.css"></head><body><?php require dirname(__DIR__) . '/layouts/admin_header.php'; ?><?php require dirname(__DIR__) . '/layouts/admin_sidebar.php'; ?>
<main class="admin-main container-fluid px-3 px-lg-4 py-4"><h1 class="h3 mb-4">Kelola Pembayaran</h1><?php if ($flash): ?><div class="alert alert-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<form class="mb-3" method="get"><select class="form-select w-auto" name="status" onchange="this.form.submit()"><option value="">Semua status</option><option <?= ($_GET['status']??'')==='Belum Dibayar'?'selected':'' ?>>Belum Dibayar</option><option <?= ($_GET['status']??'')==='Sudah Dibayar'?'selected':'' ?>>Sudah Dibayar</option></select></form>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($transactions as $transaction): ?><tr><td><?= e($transaction['transaction_code']) ?></td><td><?= e($transaction['customer_name']) ?></td><td><?= format_rupiah($transaction['total_amount']) ?></td><td><?= e($transaction['payment_status']) ?></td><td><?php if ($transaction['payment_status']==='Belum Dibayar'): ?><form method="post" action="<?= e(BASE_URL) ?>/admin/payments/confirm"><?= csrf_field() ?><input type="hidden" name="transaction_id" value="<?= e($transaction['id']) ?>"><button class="btn btn-sm btn-coffee">Konfirmasi Dibayar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
</main><?php require dirname(__DIR__) . '/layouts/admin_footer.php'; ?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
